public static long Operation(string op, long a, long b) => op switch {
    "+" => a + b, "-" => a - b, "*" => a * b, "/" => a / b, "%" => a % b, "<" => a < b ? 1 : 0, "<=" => a <= b ? 1 : 0, ">" => a > b ? 1 : 0, ">=" => a >= b ? 1 : 0, "==" => a == b ? 1 : 0, _ => a != b ? 1 : 0
};
